create schema if not exists private;
grant usage on schema private to fund_admin, expert, applicant;

create or replace function private.login() returns text language sql stable as
$$ select nullif(current_setting('request.jwt.claims',true),'')::json->>'login' $$;
create or replace function private.via() returns text language sql stable as
$$ select case when lower(coalesce(nullif(current_setting('request.headers',true),'')::json->>'x-client',''))='ai' then 'ai' else 'human' end $$;
create or replace function private.my_company() returns int language sql stable security definer set search_path=pg_catalog,api as
$$ select company_id from api.app_user where login=private.login() $$;
create or replace function private.ord(sid int) returns int language sql stable security definer set search_path=pg_catalog,api as
$$ select ord from api.status where id=sid $$;
grant execute on all functions in schema private to fund_admin, expert, applicant;

-- R6, R7 (amount is numeric: non-numeric rejected by type)
alter table api.application alter column amount set not null;
alter table api.application add constraint application_amount_nonneg check (amount >= 0);
alter table api.application alter column status_id set default 20000;

-- audit & confirmations
create table api.audit(id bigserial primary key, ts timestamptz not null default now(), actor text, via text not null check (via in ('ai','human')), op text not null, app_id int);
create table api.confirmation(id bigserial primary key, ts timestamptz not null default now(), actor text not null, op text not null check (op in ('delete','bulk_update')), app_id int, used boolean not null default false,
  check ((op='delete') = (app_id is not null)));

create or replace function private.t_confirm_ins() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
 if private.via()='ai' then raise exception 'confirmation must be given by a human, not by the agent' using errcode='42501'; end if;
 new.actor := private.login(); new.used:=false; new.ts:=now();
 return new; end $$;
create trigger confirm_ins before insert on api.confirmation for each row execute function private.t_confirm_ins();

create or replace function private.consume(p_op text, p_app int) returns boolean language plpgsql security definer set search_path=pg_catalog,api as $$
declare cid bigint;
begin
 select id into cid from api.confirmation where actor=private.login() and op=p_op and app_id is not distinct from p_app and not used and ts>now()-interval '15 minutes' order by id limit 1 for update;
 if cid is null then return false; end if;
 update api.confirmation set used=true where id=cid; return true; end $$;

create or replace function private.t_app_biu() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare o int; n int; lim numeric; r text := current_user;
begin
 n := private.ord(new.status_id);
 if n is null then raise exception 'unknown status'; end if;
 if tg_op='INSERT' then
   if n<>1 then raise exception 'new application must be in status Черновик'; end if;
 else
   o := private.ord(old.status_id);
   if n<>o then
     if n<>o+1 and not (o=3 and n=5) then raise exception 'status transition not allowed'; end if;
     if r='applicant' and not (o=1 and n=2) then raise exception 'applicant may only submit a draft'; end if;
     if r='expert' and not (o in (2,3)) then raise exception 'expert may not make this transition'; end if;
   end if;
 end if;
 if n=4 then
   select funding_limit into lim from api.company where id=new.company_id;
   if new.amount > coalesce(lim,0) then raise exception 'amount exceeds company funding limit'; end if;
 end if;
 if n in (4,5) and nullif(btrim(coalesce(new.verdict,'')),'') is null then
   raise exception 'expert verdict is required to approve or reject'; end if;
 return new; end $$;
create trigger app_biu before insert or update on api.application for each row execute function private.t_app_biu();

create or replace function private.t_app_bd() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
 if private.via()='ai' and not private.consume('delete',old.id) then
   raise exception 'delete by agent requires human confirmation (api.confirmation op=delete, app_id=%)',old.id using errcode='42501'; end if;
 return old; end $$;
create trigger app_bd before delete on api.application for each row execute function private.t_app_bd();

create or replace function private.t_app_bulk() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare c int;
begin
 select count(*) into c from nt;
 if c>1 and private.via()='ai' and not private.consume('bulk_update',null) then
   raise exception 'bulk update by agent requires human confirmation (api.confirmation op=bulk_update)' using errcode='42501'; end if;
 return null; end $$;
create trigger app_bulk after update on api.application referencing new table as nt for each statement execute function private.t_app_bulk();

create or replace function private.t_audit() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
 insert into api.audit(actor,via,op,app_id) values (coalesce(private.login(),current_user), private.via(), lower(tg_op), coalesce(new.id,old.id));
 return null; end $$;
create trigger app_audit after insert or update or delete on api.application for each row execute function private.t_audit();

-- grants
revoke all on api.audit, api.confirmation from public;
grant usage on all sequences in schema api to fund_admin, expert, applicant;
grant select on api.audit to fund_admin;
grant select, insert, delete on api.confirmation to fund_admin, expert, applicant;
grant select on api.status to expert, applicant;
grant select on api.company to expert, applicant;
revoke all on api.application from expert, applicant;
grant select (id,number,company_id,status_id,amount,revenue,description,verdict) on api.application to applicant;
grant insert (number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant update (number,status_id,amount,revenue,description) on api.application to applicant;
grant delete on api.application to applicant;
grant select on api.application to expert;
grant update (status_id,verdict,expert) on api.application to expert;
grant select, insert, delete on api.audit to fund_admin; revoke insert,delete on api.audit from fund_admin;
grant usage on all sequences in schema api to fund_admin, expert, applicant;

